"""One-time review: clinically relevant distractors, preserving correct answers."""
import json
from pathlib import Path
p=Path(__file__).resolve().parents[1]/'data/original/psychiatric.json'
d=json.loads(p.read_text(encoding='utf-8'))
updates={
18:('躁状態を予防するため単独使用が基本となる|躁転を誘発することがある|再発予防薬は併用できなくなる|症状が軽快したらすぐに自己中止する必要がある','双極症の抑うつでは、躁転等への注意が必要で、単極性うつ病と同じように単独使用を基本とはしない。|抗うつ薬によって躁状態への変化等が起こることがあり、治療内容を慎重に検討する。|再発予防薬との併用の可否を本人が決めるのではなく、病状に応じて処方医が調整する。|軽快したからと自己中止せず、継続や変更を処方医に相談する。'),
31:('徐脈と低体温|頻脈と高体温|徐脈と高体温|頻脈と低体温','著しい低栄養では代謝や循環の変化により徐脈・低体温などを認める。|低栄養で典型的なのは徐脈・低体温で、頻脈や発熱があれば別の要因も評価する。|徐脈はみられるが、高体温は低栄養の代表的変化ではない。|低体温はみられるが、低栄養の代表的な脈拍変化は徐脈である。'),
32:('血清ビリルビンと眼底|血清カリウムと心電図|血清尿酸と関節可動域|血清コレステロールと視力','ビリルビンや眼底よりも、反復嘔吐による電解質異常と循環への影響が重要である。|嘔吐の反復で低カリウム血症などを来し、不整脈の危険があるため確認する。|尿酸や関節可動域は、この場面で優先して捉える電解質異常と心臓への影響の指標ではない。|脂質や視力だけでは、反復嘔吐に伴う急性の電解質異常を評価できない。'),
33:('高リン血症が起こりやすい|体液量の減少だけに注意する|低リン血症が起こりうる|栄養開始後は電解質の確認間隔を一律に延ばす','再栄養ではリンが細胞内に移動し、血中リン低下に注意する。|水分貯留や心不全なども起こり得るため、体液の減少だけを見るのではない。|再栄養に伴う代謝変化で低リン血症が起こり得るため、慎重に観察する。|再栄養リスクがある人では、開始後も電解質や身体状態を注意深く確認する。'),
38:('変形性関節症|関節リウマチ|化膿性関節炎|骨粗鬆症','関節軟骨の変性が中心で、低栄養が長く続く場合の代表的な骨代謝の問題とは異なる。|自己免疫に関わる炎症性関節疾患で、神経性やせ症の典型的合併症ではない。|感染による関節炎で、長期低栄養に伴う代表的な骨量の問題とは異なる。|低栄養や内分泌の変化が続くと骨量が低下し、骨粗鬆症に注意する。'),
47:('悪性症候群|アカシジア|薬剤性パーキンソニズム|遅発性ジスキネジア','高熱、筋強剛、意識の変化などは悪性症候群を疑う重要な所見で、緊急の評価が必要である。|静座困難や内的な落ち着かなさが中心で、ここでの全身症状の組合せとは異なる。|振戦、筋強剛、動作緩慢などがみられるが、高熱や意識変容を伴う状態では悪性症候群を疑う。|口周囲などの不随意運動が中心で、高熱と意識変容の組合せを主に説明しない。'),
50:('身長・座高・胸囲|視力・視野・眼圧|聴力・耳漏・鼓膜所見|体重・血糖・脂質','成長等の評価に使う指標だが、非定型抗精神病薬の代謝への影響はこれだけでは捉えられない。|眼症状があれば評価するが、継続観察で重視する代謝指標の組合せではない。|耳症状の評価であり、薬物療法に伴う体重増加や糖脂質代謝の変化とは区別する。|体重増加や糖・脂質代謝の異常などに注意して継続的に確認する。'),
57:('抗凝固作用による出血傾向を確認するため|脱水による赤血球濃縮だけを確認するため|重い白血球系の減少を早期発見するため|血液型により毎回投与量を変更するため','クロザピンの重要な採血管理は、抗凝固薬の作用の評価とは異なる。|脱水の評価に限らず、特に好中球などの減少を見逃さないために採血管理を行う。|無顆粒球症などの重い血球減少に注意し、決められた採血管理を続ける。|血液型によって毎回投与量を変更するための検査ではない。'),
61:('苦痛への対処と感情調節|確認行為を繰り返して不安を下げる|不快な感情を完全に抑え込む|対立を避けるため希望を伝えない','弁証法的行動療法では苦痛耐性、感情調節、対人関係などの技能を学ぶ。|反復確認で不安を下げ続けることを目標にするのではない。|感情を否定して封じ込めるのではなく、気づきや調節を学ぶ。|自分の希望を伝えない方法ではなく、効果的な対人関係の技能を支える。'),
67:('医療保護入院の同意を家族に代わって行う|精神障害者保健福祉手帳を交付する|退院等の請求に関する審査を行う|病院管理者として身体拘束を指示する','家族等に代わって入院への同意をする機関ではない。|手帳の交付に関する手続きと、入院の必要性や退院等の請求の審査は区別する。|精神医療審査会は退院や処遇改善に関する請求等を審査する。|病院の管理者や診療担当医として拘束を指示する機関ではない。'),
77:('状況・考え・感情・行動のつながり|診断名だけで決まる固定的な性格|夢の象徴だけによる現在の判断|行動の結果を除いた思考だけ','出来事の受け止め方と感情・行動の関係を整理し、対処を検討する。|診断名で性格を固定するのではなく、具体的な状況と反応を扱う。|夢の象徴だけに基づく理解ではなく、現在の認知や行動との関係を扱う。|思考だけでなく、実際の行動やその結果も含めて検討する。'),
80:('不安を感じる状況をすべて回避する|つらい感情を言葉にしない習慣をつける|苦痛を我慢できるまで相談を延期する|身体の緊張に気づき和らげる','不安場面の一律な回避を増やすのではなく、緊張に対処する方法を学ぶ。|感情の表現を禁止するものではなく、自分の反応に気づいて調整する。|相談を遅らせるための方法ではなく、必要な支援と併せて用いる。|呼吸や筋の緊張などに気づき、過度な身体の緊張を和らげる方法を学ぶ。')
}
for q in d['questions']:
 n=int(q['id'][-3:])
 if n in updates:
  q['choices'],q['notes']=[x.split('|') for x in updates[n]]
  q['review_note']+=' 二次確認：正答を保持し関連する症状・制度・療法を比較できる選択肢に修正。'
p.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print('Revised',len(updates),'psychiatric items')
